head.script:
scwin.onpageload = function() {
	gen_test.insertChild();
	gen_test.insertChild();
	gen_test.insertChild();
	gen_noEscape.insertChild();
};

scwin.checkVal = function() {
	var spans = (document.getElementById('gen_test') || document.getElementById('mf_gen_test')).querySelectorAll('span');
	return spans.length == 3 && spans[1].innerText == '가나다<br/>가나다';
};

scwin.checkVal2 = function() {
	var outer = document.getElementById('span_noEscape') || document.getElementById('mf_span_noEscape');
	var gen = document.getElementById('gen_noEscape_0_span_genNoEscape') || document.getElementById('mf_gen_noEscape_0_span_genNoEscape');
	return outer.querySelectorAll('br').length == 1 && gen.querySelectorAll('br').length == 1 && gen.innerText == outer.innerText && gen.innerText.indexOf('&lt;') < 0;
};
